--//==============================================================
--// EMBEDDED CAT WALLPAPER
--//==============================================================
local EMBEDDED_CAT_FILE = "WindTurfCat.jpg"
local EMBEDDED_CAT_BASE64 = [[

]]

local function decodeBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do
        lookup[alphabet:sub(i, i)] = i - 1
    end

    data = data:gsub("[^%w%+/=]", "")
    local output = {}

    for i = 1, #data, 4 do
        local a = lookup[data:sub(i, i)] or 0
        local b = lookup[data:sub(i + 1, i + 1)] or 0
        local cChar = data:sub(i + 2, i + 2)
        local dChar = data:sub(i + 3, i + 3)
        local c = lookup[cChar] or 0
        local d = lookup[dChar] or 0

        local n = a * 262144 + b * 4096 + c * 64 + d
        local byte1 = math.floor(n / 65536) % 256
        local byte2 = math.floor(n / 256) % 256
        local byte3 = n % 256

        output[#output + 1] = string.char(byte1)
        if cChar ~= "=" then
            output[#output + 1] = string.char(byte2)
        end
        if dChar ~= "=" then
            output[#output + 1] = string.char(byte3)
        end
    end

    return table.concat(output)
end

local function installEmbeddedCatWallpaper()
    if type(writefile) ~= "function" then
        return false
    end

    local ok = pcall(function()
        local alreadyThere = false
        if type(isfile) == "function" then
            alreadyThere = isfile(EMBEDDED_CAT_FILE)
        end

        if not alreadyThere then
            writefile(EMBEDDED_CAT_FILE, decodeBase64(EMBEDDED_CAT_BASE64))
        end
    end)

    return ok
end

installEmbeddedCatWallpaper()

