--//==============================================================
--// CONNECTION HELPERS
--//==============================================================
local function disconnect(name)
    local connection = Connections[name]
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
        Connections[name] = nil
    end
end

local function connect(name, signal, callback)
    disconnect(name)
    local ok, connection = pcall(function()
        return signal:Connect(callback)
    end)
    if ok then
        Connections[name] = connection
        return connection
    end
    return nil
end

local function disconnectAll()
    for name in pairs(Connections) do
        disconnect(name)
    end
end

--//==============================================================
--// SAFE UTILITY HELPERS
--//==============================================================
local function notify(title, text, duration)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = tostring(title),
            Text = tostring(text),
            Duration = duration or 3
        })
    end)
end

local function tween(instance, duration, properties, style, direction)
    if not instance or not instance.Parent then
        return nil
    end

    if not State.Animations then
        for property, value in pairs(properties) do
            pcall(function()
                instance[property] = value
            end)
        end
        return nil
    end

    local ok, result = pcall(function()
        return TweenService:Create(
            instance,
            TweenInfo.new(
                duration or 0.25,
                style or Enum.EasingStyle.Quad,
                direction or Enum.EasingDirection.Out
            ),
            properties
        )
    end)

    if ok and result then
        result:Play()
        return result
    end

    return nil
end

local function isAlive()
    return Character
        and Character.Parent
        and Humanoid
        and Humanoid.Parent
        and Humanoid.Health > 0
        and RootPart
        and RootPart.Parent
end

local function refreshCharacter(char)
    Character = char
    Humanoid = nil
    RootPart = nil

    if not char then
        return
    end

    Humanoid = char:FindFirstChildOfClass("Humanoid")
    RootPart = char:FindFirstChild("HumanoidRootPart")

    if not Humanoid then
        pcall(function()
            Humanoid = char:WaitForChild("Humanoid", 8)
        end)
    end

    if not RootPart then
        pcall(function()
            RootPart = char:WaitForChild("HumanoidRootPart", 8)
        end)
    end
end

refreshCharacter(LocalPlayer.Character)

connect("CharacterAdded", LocalPlayer.CharacterAdded, function(char)
    refreshCharacter(char)

    task.delay(0.4, function()
        if State.RejoinAfterDeath and isAlive() then
            -- Rejoin-after-death is deliberately disabled after one attempt.
            State.RejoinAfterDeath = false
        end
    end)
end)

