-- Try supported local-asset APIs.
local function resolveCatAsset()
    local candidates = CONFIG.CatFileNames

    for _, filename in ipairs(candidates) do
        local ok, asset = pcall(function()
            if getcustomasset then
                return getcustomasset(filename)
            end
            return nil
        end)

        if ok and type(asset) == "string" and asset ~= "" then
            return asset
        end

        ok, asset = pcall(function()
            if getsynasset then
                return getsynasset(filename)
            end
            return nil
        end)

        if ok and type(asset) == "string" and asset ~= "" then
            return asset
        end
    end

    return nil
end

local CAT_ASSET = resolveCatAsset()
if CAT_ASSET then
    CatLayer.Image = CAT_ASSET
end

local function applyWallpaper()
    if State.Wallpaper == "Cat" then
        GalaxyLayer.Visible = false

        if CAT_ASSET then
            CatLayer.Visible = true
        else
            -- If the embedded cat asset cannot be loaded, use the plain
            -- menu background instead of leaving the galaxy on permanently.
            CatLayer.Visible = false
        end
    elseif State.Wallpaper == "Galaxy" then
        GalaxyLayer.Visible = true
        CatLayer.Visible = false
    else
        GalaxyLayer.Visible = false
        CatLayer.Visible = false
    end
end

-- Keep the normal interface off the galaxy wallpaper. The galaxy is used
