connect("GalaxyAnimation", RunService.RenderStepped, function()
    if Destroyed then
        return
    end

    if State.Wallpaper ~= "Galaxy" or not State.GalaxyAnimation then
        return
    end

    local time = os.clock()

    GalaxyGradient.Rotation =
        25 + math.sin(time * 0.22) * 10

    for index, blob in ipairs(GalaxyBlobs) do
        local x =
            0.04
            + ((index * 0.145 + time * (0.004 + index * 0.0006)) % 0.88)

        local y =
            0.04
            + ((index * 0.19
                + math.sin(time * 0.16 + index) * 0.06) % 0.88)

        blob.Position = UDim2.new(x, 0, y, 0)
    end
end)

